target.css:
:root {
  --ink: #263642;
  --paper: #fffefa;
  --line: #d6e0db;
  --moss: #476b5e;
  --mint: #e0eee5;
  --sun: #f2c96c;
  --clay: #c96648;
}

.route-card,
.route-card * {
  box-sizing: border-box;
}

.route-card {
  width: 492px;
  overflow: hidden;
  color: var(--ink);
  background-color: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.card-header,
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 18px;
}

.card-header {
  border-bottom: 1px solid var(--line);
}

.title-block p,
.title-block h1,
.kit-note p {
  margin: 0;
}

.eyebrow,
.note-label,
.meet-time span {
  color: var(--moss);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.title-block h1 {
  margin-top: 3px;
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.status {
  padding: 5px 8px;
  color: var(--moss);
  background-color: var(--mint);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.6px;
}

.route-body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 116px;
  gap: 16px;
  padding: 14px 18px;
}

.route-details {
  display: flex;
  align-items: center;
  min-width: 0;
}

.meet-time {
  display: flex;
  flex: 0 0 70px;
  flex-direction: column;
  gap: 2px;
  padding-right: 12px;
  border-right: 1px solid var(--line);
}

.meet-time strong {
  font-size: 20px;
  line-height: 1;
}

.meet-time small {
  color: var(--moss);
  font-size: 10px;
  font-weight: 700;
}

.stops {
  display: grid;
  gap: 7px;
  width: 100%;
  margin: 0;
  padding: 0 0 0 14px;
  list-style: none;
}

.stops li {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) auto;
  gap: 7px;
  align-items: center;
  font-size: 12px;
  font-weight: 600;
}

.stop-dot {
  width: 8px;
  height: 8px;
  background-color: var(--sun);
  border: 2px solid var(--ink);
  border-radius: 50%;
}

.stop-dot.start {
  background-color: var(--mint);
}

.stop-dot.end {
  background-color: var(--clay);
}

.stops time {
  color: var(--moss);
  font-size: 10px;
  font-weight: 700;
}

.kit-note {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  padding: 10px 11px;
  background-color: var(--sun);
  border-radius: 10px;
}

.kit-note p {
  font-size: 12px;
  font-weight: 600;
  line-height: 1.35;
}

.kit-note strong {
  font-size: 11px;
}

.card-footer {
  padding-top: 10px;
  padding-bottom: 10px;
  background-color: var(--mint);
}

.attendees {
  color: var(--moss);
  font-size: 12px;
  font-weight: 700;
}

.card-footer button {
  padding: 7px 10px;
  color: var(--paper);
  background-color: var(--ink);
  border: 1px solid var(--ink);
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

.card-footer button span {
  margin-left: 5px;
  color: var(--sun);
  font-size: 15px;
  line-height: 0;
}

